cd /workspace && cat > tmp/test_worker.py <<'PY'
import sys, random, math
sys.path.insert(0,'submission')
import numpy as np
from te.worker_solver import solve_worker

def check(caps,dem,paths,owned,mode,rho,B,res):
    E=len(caps); K=len(dem)
    if res['status']=='infeasible':
        unr=sorted(k for k in owned if dem[k]>0 and not any(p is not None and all(caps[e]>0 for e in p) for p in paths[k]))
        assert res['unroutable']==unr,(res,unr)
        return True
    flow=res['flow']; load=res['edge_load']; lam=res['potential']
    assert len(flow)==len(owned)==len(lam)
    assert len(load)==E
    # recompute load
    for out_i,k in enumerate(owned):
        assert len(flow[out_i])==len(paths[k])
        for p,path in enumerate(paths[k]):
            x=flow[out_i][p]
            if not (isinstance(x,(int,float)) and math.isfinite(x) and x>=0 and x<=1e9): print('bad x',x); return False
            avail=path is not None and all(caps[e]>0 for e in path)
            if not avail or dem[k]==0:
                if x!=0: print('nonzero fixed',k,p,x,avail,dem[k]); return False
            else:
                assert 0<=x<=1e9
    rec=[0.0]*E
    for out_i,k in enumerate(owned):
        for p,path in enumerate(paths[k]):
            if path is None: continue
            for e in path: rec[e]+=flow[out_i][p]
    for e in range(E):
        if caps[e]<=0:
            if load[e]!=0: print('withdraw load nonzero');return False
        if abs(rec[e]-load[e])>1e-7+1e-7*max(abs(rec[e]),abs(load[e])):
            print('load mismatch',e,rec[e],load[e]);return False
    R=sum(sum(r) for r in flow)
    ff=0.0
    for out_i,k in enumerate(owned):
        for p,x in enumerate(flow[out_i]): ff+=0.5*x*x
    for e in range(E):
        if caps[e]>0:
            ff+=0.5*rho*(load[e]/caps[e]-B[e])**2
    if mode=='admit': ff-=R
    # gradients and sums
    Gs={}
    for out_i,k in enumerate(owned):
        sm=sum(flow[out_i])
        if mode=='route':
            if abs(sm-dem[k])>1e-7+1e-7*max(abs(sm),abs(dem[k])):
                print('route sum mismatch',k,sm,dem[k]);return False
        else:
            if sm>dem[k]+1e-7+1e-7*max(abs(sm),abs(dem[k])):
                print('admit sum exceed',k,sm,dem[k]);return False
        for p,path in enumerate(paths[k]):
            if path is None or caps[k]<=0: continue
            avail=all(caps[e]>0 for e in path)
            if not avail or dem[k]<=0: continue
            g=flow[out_i][p]-(1.0 if mode=='admit' else 0.0)
            for e in path:
                g+=rho*(load[e]/caps[e]-B[e])/caps[e]
            Gs[(out_i,p)]=g
            if g+lam[out_i] < -1e-7-1e-7*max(abs(g+lam[out_i]),abs(g),abs(lam[out_i])):
                print('reduced neg',k,p,g,lam[out_i],g+lam[out_i]);return False
            if mode=='admit' and lam[out_i]<0:
                print('admit neg lam');return False
    D=ff
    for out_i,k in enumerate(owned):
        for p in range(len(paths[k])):
            if (out_i,p) in Gs:
                D-=flow[out_i][p]*Gs[(out_i,p)]
        D-=dem[k]*lam[out_i]
        if dem[k]==0 and lam[out_i]!=0:
            print('zero demand lambda');return False
    tol=1e-7+1e-7*max(abs(D),abs(ff))
    if abs(D-ff)>tol:
        print('D mismatch',D-ff,'tol',tol,'f',ff,'D',D,'rho',rho,'mode',mode,'owned',owned)
        return False
    return True

random.seed(0)
for trial in range(2000):
    E=random.randint(1,15); K=random.randint(0,6)
    caps=[random.choice([0,1,1,2,3,5,10,1000]) for _ in range(E)]
    dem=[random.randint(0,10) for _ in range(K)]
    paths=[]
    for k in range(K):
        m=random.randint(0,5)
        pp=[]
        for j in range(m):
            if random.random()<0.15: pp.append(None)
            else:
                L=random.randint(1,min(4,E))
                pp.append(random.sample(range(E),L))
        paths.append(pp)
    workers=[list(range(K))]
    owned=workers[0]
    mode=random.choice(['route','admit'])
    rho=random.choice([1,2,8])
    B=[random.uniform(-10,10) for _ in range(E)]
    res=solve_worker(caps,dem,paths,owned,mode,rho,B)
    if not check(caps,dem,paths,owned,mode,rho,B,res):
        print('TRIAL',trial,'E',E,'caps',caps,'dem',dem,'paths',paths,'mode',mode,'rho',rho,'B',B)
        print(res)
        break
else:
    print('all ok')
PY
